// Normalise every lead source into one shape, and screen out junk.
// Add a new `case` here for each channel you connect.

const out = [];

for (const item of $input.all()) {
  const b = item.json.body || item.json;
  const source = (b.source || $json.headers?.['x-lead-source'] || 'website').toLowerCase();

  let lead = {};

  switch (source) {
    case 'whatsapp':
      lead = {
        name: b.profile?.name || b.name || 'WhatsApp user',
        email: b.email || '',
        phone: b.from || b.phone || '',
        message: b.text?.body || b.message || '',
        company: b.company || ''
      };
      break;

    case 'instagram':
      lead = {
        name: b.username || b.name || 'Instagram user',
        email: b.email || '',
        phone: b.phone || '',
        message: b.text || b.message || '',
        company: ''
      };
      break;

    default: // website form (matches the LazyScale audit form field names)
      lead = {
        name: b.name || '',
        email: b.email || '',
        phone: b.phone || '',
        message: b.pain_points || b.message || '',
        company: b.startup || b.company || '',
        team_size: b.team_size || ''
      };
  }

  // ---- screening ----
  const honeypot = (b._gotcha || '').trim();
  const emailOk = /^[^@\s]+@[^@\s]+\.[^@\s]{2,}$/.test(lead.email);
  const hasContact = emailOk || String(lead.phone).replace(/\D/g, '').length >= 8;

  // Free-text goes into an LLM prompt later, so cap it hard.
  lead.message = String(lead.message).slice(0, 1500);
  lead.name = String(lead.name).slice(0, 100);
  lead.company = String(lead.company).slice(0, 100);

  let reject = '';
  if (honeypot) reject = 'honeypot';
  else if (!hasContact) reject = 'no usable contact detail';
  else if (!lead.message && !lead.company) reject = 'empty submission';

  out.push({
    json: {
      ...lead,
      source,
      email_valid: emailOk,
      received_at: new Date().toISOString(),
      valid: reject === '',
      reject_reason: reject
    }
  });
}

return out;

