// The model is told to return JSON. Never trust that blindly —
// if parsing fails we still want the lead, just without the scoring.

const lead = $('Real Lead?').first().json;
let parsed = null;

try {
  const raw = $json.content?.[0]?.text || '';
  const match = raw.match(/\{[\s\S]*\}/); // tolerate prose around the JSON
  if (match) parsed = JSON.parse(match[0]);
} catch (e) {
  parsed = null;
}

const score = Number(parsed?.score);
const valid = parsed && Number.isFinite(score) && score >= 0 && score <= 10;

return [{
  json: {
    ...lead,
    score: valid ? score : null,
    temperature: valid ? (score >= 8 ? 'hot' : score >= 5 ? 'warm' : 'cold') : 'unscored',
    summary: parsed?.summary || 'Could not auto-summarise — read the message.',
    reply_body: parsed?.reply || '',
    reply_ok: Boolean(parsed?.reply && String(parsed.reply).trim().length > 40),
    needs_human: !valid || parsed?.needs_human === true,
    parse_failed: !valid
  }
}];

