// Nothing here should ever stop the workflow — logging is best effort.
const d = $('Parse Result').first().json;

return [{
  json: {
    received_at: d.received_at,
    name: d.name,
    email: d.email,
    phone: d.phone,
    company: d.company,
    source: d.source,
    score: d.score,
    temperature: d.temperature,
    summary: d.summary,
    auto_replied: d.reply_ok && !d.needs_human && d.email_valid,
    needs_human: d.needs_human,
    parse_failed: d.parse_failed,
    message: d.message
  }
}];

// Rejected submissions land here. Keep a count so you can see if you are
// being hammered, but do not spend an LLM call on them.
return [{ json: { dropped: true, reason: $json.reject_reason, at: new Date().toISOString(), source: $json.source } }];
